import type { FnContext } from './context';
import type { Opt, ReportKind } from './rows';

export type EntryKind = "you" | "agent" | "from_agent" | "tools" | "card" | "page" | "report" | "stopped" | "to_agent";

/**
 * What a tool call did, for the counted summary.
 */
export type ToolKind = "read" | "edit" | "run" | "search" | "other";

export type ToolItem = { pos: number, at_ms: number, 
/**
 * its intent ("running the tests"), else `name: first line of args`
 */
text: string, kind: ToolKind, 
/**
 * a `sb land`
 */
land?: boolean, };

export type Tools = { count: number, 
/**
 * counted words: "read 6 files, ran 4 commands"
 */
summary: string, items: Array<ToolItem>, };

export type EntryCard = { id: number, question: string, options: Array<Opt>, answered: boolean, };

export type PageRef = { id: string, title: string, v?: number | null, url: string, };

export type ReportRef = { kind: ReportKind, };

/**
 * One entry of a thread.
 */
export type Entry = { 
/**
 * its first line's transcript position (`<agent>#<pos>`)
 */
pos: number, at_ms: number, kind: EntryKind, 
/**
 * markdown
 */
text: string, from?: string | null, tools?: Tools | null, card?: EntryCard | null, page?: PageRef | null, report?: ReportRef | null, 
/**
 * his message's fn context (S9): what was on his screen when he
 * spoke, from the `sb context : <json>` line right after his 'you'
 * line (the window draws the shot and the app on his message)
 */
context?: FnContext | null, 
/**
 * a `to_agent` entry: who it went to
 */
to?: string | null, 
/**
 * a `to_agent` entry: it waits for the reply (its question)
 */
asks?: boolean, 
/**
 * a `to_agent` entry: its message id (`m_12` is 12; the card main
 * opens for it says `for` the same)
 */
msg?: number | null, };
